const Indexers = () => (
  <Select defaultValue={indexers[0].uri}>
    <SelectTrigger className="w-72">
      <SelectValue placeholder="Pick an Indexer" />
    </SelectTrigger>
    <SelectContent>
      {indexers.map((indexer) => (
        <SelectItem key={indexer.uri} value={indexer.uri}>
          {indexer.label}
        </SelectItem>
      ))}
    </SelectContent>
  </Select>
);
